<?php
$where = ["t.statut <> 'vendu'"];
$params = [];
$zone = trim((string) ($_GET['zone'] ?? ''));
$legal = (string) ($_GET['legal'] ?? '');
$type = (string) ($_GET['type'] ?? '');
$min = filter_input(INPUT_GET, 'min', FILTER_VALIDATE_FLOAT);
$max = filter_input(INPUT_GET, 'max', FILTER_VALIDATE_FLOAT);
$area = filter_input(INPUT_GET, 'area', FILTER_VALIDATE_FLOAT);
if ($zone !== '') { $where[] = 't.zone_commune LIKE :zone'; $params['zone'] = '%' . $zone . '%'; }
if (in_array($type, ['terrain','maison','lot_loti'], true)) { $where[] = 't.type_bien = :type'; $params['type'] = $type; }
if ($legal !== '' && in_array($legal, ['Titre Foncier', 'ACD', 'Attestation Villageoise', 'À vérifier'], true)) { $where[] = 't.statut_juridique = :legal'; $params['legal'] = $legal; }
if ($min !== false && $min !== null) { $where[] = 't.prix >= :min'; $params['min'] = $min; }
if ($max !== false && $max !== null) { $where[] = 't.prix <= :max'; $params['max'] = $max; }
if ($area !== false && $area !== null) { $where[] = 't.superficie >= :area'; $params['area'] = $area; }
$sql = "SELECT t.*, (SELECT p.id FROM photos_terrains p WHERE p.terrain_id=t.id AND p.type='photo' ORDER BY p.id LIMIT 1) AS photo_id, (SELECT AVG(a.note) FROM avis_terrains a WHERE a.terrain_id=t.id AND a.statut='publie') AS rating_avg, (SELECT COUNT(*) FROM avis_terrains a WHERE a.terrain_id=t.id AND a.statut='publie') AS rating_count FROM terrains t WHERE " . implode(' AND ', $where) . ' ORDER BY t.date_publication DESC';
$stmt = db()->prepare($sql);
$stmt->execute($params);
$lands = $stmt->fetchAll();
?>
