?><div class="property-grid catalog-grid"><?php foreach ($lands as $land): ?><article class="property-card"><a class="property-image" href="?page=terrain&id=<?= (int)$land['id'] ?>"><?php if ($land['photo_id']): ?><img src="?page=media&id=<?= (int)$land['photo_id'] ?>" alt="Photo de <?= e($land['titre']) ?>" loading="lazy"><?php else: ?><div class="image-placeholder"><span>SG</span></div><?php endif; ?><span class="property-tag"><?= e(ucfirst(str_replace('_',' ',$land['type_bien']))) ?></span></a><div class="property-body"><div class="property-location">⌖ <?= e($land['zone_commune']) ?></div><h3><a href="?page=terrain&id=<?= (int)$land['id'] ?>"><?= e($land['titre']) ?></a></h3><?= star_rating((float)($land['rating_avg'] ?? 0),(int)$land['rating_count']) ?><div class="property-facts"><span><?= number_format((float)$land['superficie'],0,',',' ') ?> m²</span><span><?= e($land['statut_juridique']) ?></span></div><div class="property-price"><?= number_format((float)$land['prix'],0,',',' ') ?> <small>FCFA</small></div></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state compact"><h3>Aucun bien ne correspond à ces critères.</h3><p>Modifiez les filtres ou demandez à notre équipe de vous aider dans votre recherche.</p><a href="?page=contact" class="text-link">Contacter l’équipe →</a></div><?php endif; ?></div></section>